/* Lote 11 — Eleitoral, Internacional, Financeiro, Ambiental, ECA, Consumidor e Previdenciário. Alternativa correta no índice 0. */
addQ("eleit","eleit","xl",1,[
["Crimes eleitorais","Segundo o Código Eleitoral, desde cinco dias antes e até quarenta e oito horas depois do encerramento da eleição, nenhuma autoridade poderá prender ou deter eleitor, salvo:",["em flagrante delito, por sentença criminal condenatória por crime inafiançável ou por desrespeito a salvo-conduto","por ordem de prisão preventiva de qualquer natureza","por prisão civil de devedor de alimentos ou por ordem de prisão preventiva de qualquer natureza, desde que expedida antes do pleito","por determinação do delegado de polícia em qualquer crime"],"A regra protege o exercício do voto. Para os candidatos, a proteção começa quinze dias antes da eleição.","Art. 236 do Código Eleitoral (Lei 4.737/1965)"],
["Partidos políticos","Segundo a Constituição, com a EC 97/2017, o acesso dos partidos aos recursos do fundo partidário e à propaganda gratuita no rádio e na televisão:",["depende do cumprimento da cláusula de desempenho nas eleições para a Câmara dos Deputados","é garantido a todos os partidos registrados, sem condições","depende de o partido ter elegido o Presidente da República","depende de autorização anual do TSE, sem critérios fixos"],"A cláusula de desempenho exige votação mínima ou número mínimo de deputados eleitos, distribuídos pelos Estados.","Art. 17, §3º, da Constituição (EC 97/2017)",["A EC 97/2017 criou condições.","O critério é a votação para a Câmara.","A Constituição fixa os critérios."]],
["Partidos políticos","Segundo a Constituição, é vedada aos partidos políticos:",["a utilização de organização paramilitar","a participação em eleições municipais","a filiação de servidores públicos","a criação de fundações de pesquisa"],"A Constituição também exige caráter nacional e proíbe recursos de entidade ou governo estrangeiros.","Art. 17, §4º, da Constituição",["Partidos participam de eleições em todos os níveis.","Servidores podem filiar-se, com restrições a algumas carreiras.","Partidos podem manter fundações (Lei 9.096/1995)."]],
["Fidelidade partidária","Ao eleito por partido que não cumpriu a cláusula de desempenho, segundo a Constituição:",["é assegurado o mandato e facultada a filiação a outro partido que a tenha cumprido, sem perda do mandato","é retirado o mandato, que passa ao suplente do partido que cumpriu a cláusula de desempenho na mesma circunscrição","é proibida a troca de partido até o fim do mandato","é assegurado o mandato só se ele renunciar à filiação"],"Essa é uma exceção constitucional à regra da fidelidade partidária.","Art. 17, §5º, da Constituição (EC 97/2017)",["O mandato é assegurado, com possibilidade de troca de partido.","A Constituição permite a troca.","Não há essa condição."]],
["Condições de elegibilidade","Segundo a legislação eleitoral, as condições de elegibilidade e as causas de inelegibilidade devem ser aferidas:",["no momento da formalização do pedido de registro, ressalvadas as alterações posteriores que afastem a inelegibilidade","no dia da eleição, para todas as condições, inclusive a idade mínima, ainda que a inelegibilidade seja afastada depois do registro","no dia da posse, para todas as condições","na data da convenção partidária"],"A regra estava no art. 11, §10, da Lei 9.504/1997, revogado pela LC 219/2025, que a transferiu para o art. 26-D da LC 64/1990: as alterações que afastem a inelegibilidade valem se ocorrerem até a diplomação. A idade mínima tem regra própria (art. 11, §2º, da Lei 9.504/1997).","Art. 26-D da LC 64/1990 (LC 219/2025)",["Aferem-se no pedido de registro, ressalvadas as alterações posteriores que afastem a inelegibilidade.","Só a idade, em regra, é aferida na posse.","A convenção não é o marco."]],
["Súmula Vinculante 18","A dissolução do vínculo conjugal no curso do mandato:",["não afasta a inelegibilidade reflexa do cônjuge","afasta a inelegibilidade reflexa, se ocorrer 6 meses antes do pleito","afasta a inelegibilidade em qualquer caso","só afasta a inelegibilidade se houver filhos menores"],"O STF ressalvou apenas a extinção do vínculo por morte.","Súmula Vinculante 18"],
["Condutas vedadas","No ano em que se realizar eleição, segundo a Lei 9.504/1997, a distribuição gratuita de bens, valores ou benefícios pela Administração:",["é proibida, salvo calamidade, emergência ou programas sociais autorizados em lei e já em execução orçamentária no exercício anterior","é permitida livremente, se houver previsão no orçamento","é proibida apenas nos três dias anteriores à eleição e permitida nos demais, desde que o candidato não participe da entrega e haja previsão no orçamento do ano","é permitida se o candidato não participar da entrega"],"A regra evita o uso da máquina pública para conquistar votos.","Art. 73, §10, da Lei 9.504/1997",["A previsão orçamentária, sozinha, não basta.","A vedação vale para todo o ano eleitoral, com as exceções legais.","A vedação independe da presença do candidato."]],
["Ações eleitorais","Segundo a Lei 9.504/1997, a representação por captação ou gastos ilícitos de recursos de campanha pode ser proposta:",["no prazo de quinze dias da diplomação, e, comprovado o ilícito, será negado ou cassado o diploma","até cinco dias antes da eleição, com pena apenas de multa","a qualquer tempo, durante o mandato","apenas pelo Ministério Público, até a posse"],"É a representação do art. 30-A.","Art. 30-A da Lei 9.504/1997",["A sanção é a negativa ou cassação do diploma.","Há prazo de quinze dias da diplomação.","Partidos também podem propor."]],
["Propaganda","Segundo a Lei 9.504/1997, o funcionamento de alto-falantes ou amplificadores de som na campanha somente é permitido:",["entre as 8 e as 22 horas, vedada a instalação a menos de 200 metros de sedes de Poderes, hospitais e escolas","entre as 6 e as 24 horas, em qualquer local","apenas nos fins de semana","apenas no dia da eleição, até as 17 horas, e nos fins de semana anteriores, sem restrição de local de instalação"],"Para comícios, o horário vai das 8 às 24 horas, com prorrogação de duas horas no comício de encerramento.","Art. 39, §§3º e 4º, da Lei 9.504/1997",["O horário é das 8 às 22 horas, e há restrição de local.","A lei não restringe a fins de semana.","É permitido entre 8 e 22 horas, com restrição de distância de sedes de Poderes, hospitais e escolas."]],
["Justiça Eleitoral","Segundo o Código Eleitoral, as juntas eleitorais compõem-se de:",["um juiz de direito, que as preside, e de dois ou quatro cidadãos de notória idoneidade","três juízes de direito e cinco cidadãos indicados pelos partidos que participam do pleito","cinco cidadãos indicados pelos partidos","um desembargador e dois advogados"],"As juntas apuram as eleições na zona eleitoral.","Art. 36 do Código Eleitoral (Lei 4.737/1965)",["As juntas têm um juiz de direito, presidente, e dois ou quatro cidadãos de notória idoneidade.","Os cidadãos não são indicados pelos partidos.","Não há desembargador na junta."]],
["Federações","Os partidos que formarem federação partidária devem permanecer filiados a ela por, no mínimo:",["4 anos","2 anos","8 anos","até o fim da eleição"],"A federação tem abrangência nacional e funciona como se fosse um único partido.","Art. 11-A da Lei 9.096/1995"],
["Alistamento","Segundo o Código Eleitoral, para fins de inscrição, domicílio eleitoral é:",["o lugar de residência ou moradia do requerente, e, havendo mais de uma, qualquer delas","o lugar de nascimento do eleitor ou aquele em que ele tem imóvel próprio registrado em seu nome","o lugar em que o eleitor tem imóvel próprio","sempre a capital do Estado em que reside"],"O TSE admite ainda vínculos políticos, sociais, profissionais ou familiares para fixar o domicílio eleitoral.","Art. 42, parágrafo único, do Código Eleitoral (Lei 4.737/1965)",["É domicílio eleitoral o lugar de residência ou moradia, e, havendo mais de uma, qualquer delas.","Não se exige imóvel próprio.","A capital não é o critério."]],
["Alistamento","Segundo a Lei 9.504/1997, nenhum requerimento de inscrição eleitoral ou de transferência será recebido dentro dos:",["150 dias anteriores à data da eleição","30 dias anteriores à data da eleição","12 meses anteriores à data da eleição","6 meses anteriores à data da eleição"],"É o fechamento do cadastro eleitoral, que permite organizar as eleições.","Art. 91 da Lei 9.504/1997",["Trinta dias não é o prazo.","Doze meses não é o prazo.","Seis meses é o prazo de filiação partidária, e não do cadastro."]],
["Direitos políticos","Segundo a Constituição, é cláusula pétrea:",["o voto direto, secreto, universal e periódico","o voto obrigatório","o sistema proporcional para Deputados","a reeleição para cargos do Executivo"],"O voto obrigatório não é cláusula pétrea, e pode ser alterado por emenda.","Art. 60, §4º, II, da Constituição",["A obrigatoriedade do voto não está no art. 60, §4º.","O sistema eleitoral pode ser alterado por emenda.","A reeleição foi criada por emenda e pode ser alterada."]],
["Financiamento","No julgamento da ADI 4.650, o STF decidiu que:",["são inconstitucionais as doações de pessoas jurídicas para campanhas eleitorais","as doações de pessoas físicas são proibidas","os partidos não podem receber recursos públicos","as doações de empresas são permitidas até 2% do faturamento"],"Desde então, as campanhas são financiadas por recursos públicos e doações de pessoas físicas.","STF, ADI 4.650",["Pessoas físicas podem doar, com limite.","Há fundo partidário e fundo eleitoral.","O STF proibiu as doações de empresas."]]
]);
addQ("inter","inter","xi",1,[
["Tratados","Segundo a Convenção de Viena sobre o Direito dos Tratados, o Estado que assinou um tratado, mas ainda não o ratificou:",["deve abster-se de atos que frustrem o objeto e a finalidade do tratado","já está obrigado a cumprir todas as suas cláusulas","não tem qualquer obrigação em relação ao tratado","pode ser processado na CIJ por não cumprir o tratado"],"É o dever de boa-fé no período anterior à entrada em vigor.","Art. 18 da Convenção de Viena sobre o Direito dos Tratados (1969)",["A obrigação plena só surge com a ratificação e a entrada em vigor.","Há o dever de não frustrar o objeto.","Não há responsabilidade por descumprimento de tratado ainda não vigente."]],
["Tratados","Segundo a Convenção de Viena sobre o Direito dos Tratados, uma mudança fundamental de circunstâncias:",["pode ser invocada para extinguir ou retirar-se de um tratado, em hipóteses excepcionais, mas não de tratados que estabeleçam limites","nunca pode ser invocada, pois os tratados são imutáveis","autoriza o Estado a descumprir qualquer tratado a qualquer tempo","só pode ser invocada pela ONU, por meio do Conselho de Segurança, que decide se o tratado deve ser extinto para todas as partes envolvidas"],"É a cláusula rebus sic stantibus, admitida de forma restrita.","Art. 62 da Convenção de Viena sobre o Direito dos Tratados (1969)",["A Convenção admite a cláusula em casos excepcionais.","A regra é restritiva.","O próprio Estado parte pode invocar a mudança fundamental, em hipóteses excepcionais, salvo tratados de limites."]],
["Direito interno","Segundo a Convenção de Viena sobre o Direito dos Tratados, um Estado:",["não pode invocar disposições de seu direito interno para justificar o inadimplemento de um tratado","pode deixar de cumprir o tratado se uma lei interna posterior o contrariar","pode suspender o tratado sempre que sua Constituição for alterada","só está obrigado ao tratado após aprovação por lei complementar"],"É a regra do art. 27, ligada ao pacta sunt servanda (art. 26).","Arts. 26 e 27 da Convenção de Viena sobre o Direito dos Tratados"],
["Tratados no Brasil","Segundo o STF (ADI 1.625, 2023), a denúncia de tratado internacional aprovado pelo Congresso Nacional pelo Presidente da República:",["depende de aprovação do Congresso para produzir efeitos no direito interno","é ato exclusivo do Presidente, que não depende do Congresso","depende de aprovação do STF","é proibida"],"O STF fixou a tese com efeitos para o futuro, preservando denúncias anteriores.","STF, ADI 1.625 e ADC 39",["O STF exigiu a participação do Congresso.","O STF não aprova denúncias.","A denúncia é possível."]],
["LINDB","Segundo a LINDB, quando a pessoa não tiver domicílio:",["considera-se domiciliada no lugar de sua residência ou naquele em que se encontre","aplica-se sempre a lei brasileira, qualquer que seja o lugar em que a pessoa se encontre","aplica-se a lei de sua nacionalidade","não pode exercer atos da vida civil"],"A regra resolve a falta de domicílio para fins da lei pessoal.","Art. 7º, §8º, da LINDB",["Sem domicílio, considera-se o lugar da residência ou onde a pessoa se encontre.","A LINDB adota o domicílio, e não a nacionalidade.","A falta de domicílio não gera incapacidade."]],
["LINDB","A sucessão de bens de estrangeiros situados no Brasil, segundo a LINDB e a Constituição, será regulada pela lei brasileira:",["em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do falecido","sempre, qualquer que seja a nacionalidade dos herdeiros","nunca, pois prevalece a lei da nacionalidade","apenas se o falecido tiver morado no Brasil por pelo menos dez anos antes da morte, sem levar em conta a nacionalidade dos herdeiros"],"Aplica-se a lei mais favorável ao cônjuge ou filhos brasileiros.","Art. 10, §1º, da LINDB; art. 5º, XXXI, da Constituição",["A regra depende de ser mais favorável aos brasileiros.","A lei brasileira pode ser aplicada.","A lei brasileira se aplica em benefício do cônjuge ou filhos brasileiros, se a lei pessoal do falecido não for mais favorável."]],
["Nacionalidade","É brasileiro nato o nascido no estrangeiro, de pai ou mãe brasileiro:",["desde que registrado em repartição brasileira competente ou que venha a residir no Brasil e opte, a qualquer tempo, após a maioridade, pela nacionalidade brasileira","em qualquer caso, independentemente de registro em repartição brasileira, de residência no Brasil ou de opção pela nacionalidade feita pelo próprio interessado após a maioridade","apenas se o pai ou a mãe estiver a serviço do Brasil","apenas se vier a residir no Brasil antes dos 18 anos"],"Se o pai ou a mãe estiver a serviço do Brasil, a nacionalidade é automática (alínea b).","Art. 12, I, b e c, da Constituição"],
["LINDB","Segundo a LINDB, a obrigação resultante de contrato reputa-se constituída:",["no lugar em que residir o proponente","no lugar em que residir o aceitante","no lugar de cumprimento da obrigação","no Brasil, sempre"],"A regra complementa o caput do art. 9º, que manda aplicar a lei do país em que se constituírem as obrigações.","Art. 9º, §2º, da LINDB",["O critério é a residência do proponente.","O lugar de cumprimento não é o critério dessa regra.","A LINDB não manda aplicar sempre a lei brasileira."]],
["LINDB","Segundo a LINDB, as sociedades e as fundações obedecem à lei:",["do Estado em que se constituírem","do domicílio de seus sócios","do lugar onde tiverem filiais","sempre brasileira"],"Para funcionar no Brasil, porém, dependem de aprovação do governo brasileiro (art. 11, §1º).","Art. 11 da LINDB",["O domicílio dos sócios não é o critério.","As filiais não definem a lei aplicável.","A lei é a do Estado de constituição."]],
["Diplomacia","Segundo a Convenção de Viena sobre Relações Diplomáticas, os locais da missão diplomática:",["são invioláveis, e os agentes do Estado acreditado não podem neles entrar sem consentimento do chefe da missão","são território do Estado estrangeiro, para todos os efeitos","podem ser revistados pela polícia local com ordem judicial","perdem a inviolabilidade em caso de crime comum, podendo a polícia local entrar sem autorização para prender o suspeito"],"A inviolabilidade não transforma a embaixada em território estrangeiro, mas impede a entrada sem consentimento.","Art. 22 da Convenção de Viena sobre Relações Diplomáticas (1961)",["A embaixada não é território estrangeiro.","Nem com ordem judicial a polícia pode entrar sem consentimento.","Os locais da missão são invioláveis; a entrada exige consentimento do chefe da missão."]],
["Nacionalidade","Segundo a Lei de Migração, a naturalização extraordinária será concedida à pessoa fixada no Brasil:",["há mais de quinze anos ininterruptos e sem condenação penal, desde que a requeira","há mais de quatro anos, com domínio da língua portuguesa","há mais de um ano, se originária de país lusófono","em qualquer caso, se casada com brasileiro"],"A naturalização extraordinária também está prevista no art. 12, II, b, da Constituição.","Art. 67 da Lei 13.445/2017; art. 12, II, b, da Constituição",["Quatro anos é requisito da naturalização ordinária.","Um ano é regra para originários de países de língua portuguesa (art. 12, II, a).","O casamento reduz prazos, mas não dá naturalização automática."]],
["Migração","Entre os princípios da Lei de Migração está:",["a não criminalização da migração","a prioridade da segurança nacional sobre os direitos do migrante","a exigência de visto para a solicitação de refúgio","a prisão administrativa do migrante irregular"],"Ninguém será privado de liberdade por razões migratórias, salvo nos casos previstos em lei.","Arts. 3º, III, e 123 da Lei 13.445/2017"],
["Extradição","Segundo a Constituição, a extradição solicitada por Estado estrangeiro é processada e julgada:",["pelo Supremo Tribunal Federal","pelo Superior Tribunal de Justiça","pela Justiça Federal de primeira instância","pelo Ministério das Relações Exteriores"],"O STF examina a legalidade do pedido. A decisão final de entregar o extraditando é do Presidente da República.","Art. 102, I, g, da Constituição",["O STJ homologa sentenças estrangeiras, mas não julga extradição.","A Justiça Federal não julga a extradição passiva.","O Itamaraty não julga."]],
["Organizações internacionais","As organizações internacionais intergovernamentais:",["são criadas por tratado entre Estados e têm personalidade jurídica de direito internacional","são criadas por lei interna de um Estado","não têm personalidade jurídica própria","são organizações não governamentais de direito privado"],"A CIJ reconheceu a personalidade da ONU no parecer sobre Reparação de Danos (1949).","Doutrina; Carta da ONU; Parecer consultivo da CIJ (1949)"],
["Refúgio","O princípio do non-refoulement proíbe:",["a devolução do refugiado a território onde sua vida ou liberdade estejam ameaçadas","a concessão de refúgio a quem ingressou de forma irregular","a extradição de brasileiros","a naturalização de refugiados"],"O princípio está na Convenção de 1951 e na Lei 9.474/1997.","Art. 33 da Convenção de 1951; art. 37 da Lei 9.474/1997"]
]);
addQ("fin","fin","xn",1,[
["Leis orçamentárias","Segundo a Constituição, o projeto de lei orçamentária anual será acompanhado de demonstrativo regionalizado do efeito, sobre as receitas e despesas, decorrente de:",["isenções, anistias, remissões, subsídios e benefícios de natureza financeira, tributária e creditícia","operações de crédito por antecipação de receita","precatórios judiciais pendentes de pagamento","transferências voluntárias aos Municípios e de convênios firmados com entidades privadas sem fins lucrativos"],"O demonstrativo mostra quanto o Estado deixa de arrecadar ou gasta com benefícios fiscais e financeiros, dando transparência a essas renúncias.","Art. 165, §6º, da Constituição"],
["LOA", "Segundo a Constituição, os recursos que, em decorrência de veto, emenda ou rejeição do projeto de lei orçamentária anual, ficarem sem despesas correspondentes:", ["poderão ser utilizados mediante créditos especiais ou suplementares, com prévia e específica autorização legislativa", "devem ser devolvidos ao Tesouro, sem possibilidade de uso no exercício", "podem ser usados livremente pelo Executivo, por decreto", "ficam automaticamente destinados ao pagamento da dívida pública"], "Esses recursos não se perdem: podem ser aproveitados por créditos especiais ou suplementares, mas sempre com autorização prévia e específica do Legislativo.", "Art. 166, §8º, da Constituição"],
["Vedações","Segundo a Constituição, é vedado o início de programas ou projetos:",["não incluídos na lei orçamentária anual","sem aprovação do Tribunal de Contas","que durem mais de um ano","que não tenham sido propostos pelo Legislativo"],"A vedação reforça o princípio da legalidade da despesa: sem previsão na LOA, não há programa.","Art. 167, I, da Constituição",["O Tribunal de Contas não aprova previamente programas.","Programas plurianuais são possíveis, com inclusão no PPA.","A iniciativa das leis orçamentárias é do Executivo."]],
["Vedações","Segundo a Constituição, nenhum investimento cuja execução ultrapasse um exercício financeiro poderá ser iniciado:",["sem prévia inclusão no plano plurianual, ou sem lei que autorize a inclusão, sob pena de crime de responsabilidade","sem autorização do Senado Federal por resolução","sem prévia aprovação em referendo popular, convocado pelo Congresso Nacional para cada obra plurianual de grande porte","sem parecer do Tribunal de Contas da União"],"O PPA é o planejamento de médio prazo que deve abrigar os investimentos plurianuais.","Art. 167, §1º, da Constituição",["A Constituição não exige resolução do Senado.","O investimento plurianual exige prévia inclusão no PPA ou lei que a autorize, sob pena de crime de responsabilidade.","Não há parecer prévio do TCU."]],
["Vedações","Segundo a Constituição, a transposição, o remanejamento ou a transferência de recursos de uma categoria de programação para outra:",["dependem de prévia autorização legislativa, salvo a exceção para ciência, tecnologia e inovação por ato do Executivo","podem ser feitos livremente por decreto","dependem de autorização do Tribunal de Contas","são proibidos em qualquer caso, mesmo com autorização legislativa, pois alteram a lei orçamentária anual já aprovada"],"A EC 85/2015 permitiu esses remanejamentos por ato do Executivo nas atividades de ciência, tecnologia e inovação.","Art. 167, VI e §5º, da Constituição",["Decreto, em regra, não basta.","O Tribunal de Contas não autoriza.","Dependem de prévia autorização legislativa, com exceção para ciência, tecnologia e inovação."]],
["Processo orçamentário","Segundo a Constituição, os recursos das dotações orçamentárias do Legislativo, do Judiciário, do Ministério Público e da Defensoria Pública ser-lhes-ão entregues:",["até o dia 20 de cada mês, em duodécimos","no início do exercício, de uma só vez","trimestralmente, conforme a arrecadação","somente após a aprovação das contas do ano anterior"],"Os duodécimos garantem a autonomia financeira desses órgãos.","Art. 168 da Constituição",["A entrega é mensal.","A entrega é mensal, e não trimestral.","A entrega não depende da aprovação das contas."]],
["LRF","Para se adequar ao limite da despesa com pessoal, a Constituição manda adotar, em primeiro lugar:",["a redução de pelo menos 20% das despesas com cargos em comissão e funções de confiança e a exoneração dos servidores não estáveis","a exoneração dos servidores estáveis, com indenização de um mês de remuneração por ano de serviço, antes de qualquer outra medida","a redução dos salários de todos os servidores","a suspensão do pagamento das aposentadorias"],"Só se essas medidas não bastarem, o servidor estável pode perder o cargo, com indenização.","Art. 169, §§3º e 4º, da Constituição",["A exoneração de estáveis é a última medida; antes vêm o corte de 20% em comissionados e a exoneração dos não estáveis.","A Constituição não prevê redução geral de salários nessa regra.","Não há suspensão de aposentadorias."]],
["Despesa pública","Segundo a Lei 4.320/1964, classificam-se como despesas de capital:",["os investimentos, as inversões financeiras e as transferências de capital","as despesas de custeio e as transferências correntes","os salários dos servidores","os juros da dívida pública"],"Despesas correntes: custeio e transferências correntes. Despesas de capital: investimentos, inversões financeiras e transferências de capital.","Art. 12 da Lei 4.320/1964",["Essas são despesas correntes.","Pessoal é despesa corrente.","Juros são despesas correntes."]],
["LRF","Segundo a Lei de Responsabilidade Fiscal, na esfera estadual, o limite da despesa com pessoal do Poder Executivo é de:",["49% da receita corrente líquida","60% da receita corrente líquida","54% da receita corrente líquida","6% da receita corrente líquida"],"No Estado, os 60% se repartem: 3% Legislativo (com o TCE), 6% Judiciário, 49% Executivo e 2% Ministério Público.","Art. 20, II, da LC 101/2000",["Sessenta por cento é o limite global do Estado.","Cinquenta e quatro por cento é o limite do Executivo municipal.","Seis por cento é o limite do Judiciário estadual."]],
["Precatórios","Segundo a Constituição, com a redação da EC 136/2025, é obrigatória a inclusão no orçamento da verba para pagamento dos precatórios apresentados:",["até 1º de fevereiro, com pagamento até o final do exercício seguinte","até 2 de abril, com pagamento no mesmo exercício em que forem apresentados","até 1º de julho, com pagamento até o final do exercício seguinte, como na redação original","a qualquer tempo, com pagamento imediato"],"A data de corte já foi 1º de julho e, depois da EC 114/2021, 2 de abril. A EC 136/2025 a antecipou para 1º de fevereiro.","Art. 100, §5º, da Constituição (EC 136/2025)",["2 de abril era a data da EC 114/2021, e o pagamento sempre ocorre até o fim do exercício seguinte.","1º de julho era a data anterior à EC 114/2021.","Não há pagamento imediato no regime de precatórios."]],
["RPV","As obrigações definidas em lei como de pequeno valor que a Fazenda deva pagar em virtude de sentença judicial:",["dispensam a expedição de precatório","também exigem precatório, em ordem cronológica própria","só podem ser pagas no exercício seguinte","devem ser compensadas com tributos devidos pelo credor"],"Na União, o limite é de 60 salários mínimos (Lei 10.259/2001).","Art. 100, §3º, da Constituição"],
["Tribunal de Contas","Segundo a Constituição, compete ao Tribunal de Contas da União:",["julgar as contas dos administradores e demais responsáveis por dinheiros, bens e valores públicos","julgar as contas anuais do Presidente da República","julgar crimes de responsabilidade de Ministros","anular contratos administrativos por conta própria, sem participação do Congresso"],"As contas do Presidente são julgadas pelo Congresso; o TCU só emite parecer prévio. Nos contratos, a sustação cabe ao Congresso (art. 71, §1º).","Art. 71, II, da Constituição",["O TCU só emite parecer sobre as contas do Presidente.","O TCU não julga crimes.","A sustação de contratos é do Congresso."]],
["Tribunal de Contas","Segundo a Constituição, o Tribunal de Contas da União é integrado por:",["nove Ministros","onze Ministros","sete Conselheiros","quinze Ministros"],"Os Tribunais de Contas dos Estados têm sete Conselheiros (art. 75, parágrafo único).","Art. 73 da Constituição",["Onze é o número de Ministros do STF.","Sete é o número de Conselheiros dos TCEs.","Quinze não é o número."]],
["Gastos mínimos","Na educação, a União deve aplicar anualmente, no mínimo:",["18% da receita resultante de impostos, e os Estados, o DF e os Municípios, 25%","25% da receita de impostos, e os demais entes, 18%","15% da receita corrente líquida, para todos os entes","12% da receita de impostos"],"Na saúde, os percentuais são outros (15% da RCL na União; 12% nos Estados; 15% nos Municípios).","Art. 212 da Constituição"],
["Repartição de receitas","Segundo a Constituição, é vedada a retenção dos recursos de repartição de receitas destinados a Estados e Municípios, mas a União e os Estados podem condicionar a entrega:",["ao pagamento de seus créditos, inclusive de suas autarquias, e ao cumprimento dos gastos mínimos com saúde","à aprovação das contas pelo Tribunal de Contas da União","ao alinhamento político do ente beneficiado com o governo que repassa os recursos e à adesão a programas federais","à realização de obras definidas pelo Presidente"],"A regra é a entrega sem retenção. As exceções são os créditos do ente que repassa e o cumprimento do mínimo em saúde.","Art. 160, caput e parágrafo único, da Constituição"]
]);
addQ("amb","amb","xo",1,[
["Meio ambiente na Constituição","O meio ambiente ecologicamente equilibrado é, segundo a Constituição:",["bem de uso comum do povo e essencial à sadia qualidade de vida, cabendo ao Poder Público e à coletividade defendê-lo","bem dominical da União, administrado pelo IBAMA, cabendo exclusivamente ao Poder Público, e não à coletividade, defendê-lo e preservá-lo","bem de propriedade exclusiva dos Estados","direito disponível de cada proprietário"],"O dever de proteção alcança as presentes e as futuras gerações.","Art. 225 da Constituição"],
["Constituição","Segundo a Constituição, as terras devolutas ou arrecadadas pelos Estados, por ações discriminatórias, necessárias à proteção dos ecossistemas naturais:",["são indisponíveis","podem ser vendidas livremente","pertencem à União","devem ser destinadas à reforma agrária"],"A indisponibilidade impede a alienação dessas terras.","Art. 225, §5º, da Constituição",["A Constituição as torna indisponíveis.","A regra não as transfere à União.","A Constituição as destina à proteção ambiental."]],
["PNMA","Segundo a Lei 6.938/1981, é instrumento da Política Nacional do Meio Ambiente:",["o zoneamento ambiental","a desapropriação por utilidade pública","o tombamento","a usucapião especial"],"Também são instrumentos os padrões de qualidade, a avaliação de impactos e o licenciamento, entre outros.","Art. 9º, II, da Lei 6.938/1981",["A desapropriação não está na lista do art. 9º.","O tombamento é instrumento de proteção cultural.","A usucapião não é instrumento da PNMA."]],
["Responsabilidade penal","Segundo a Lei 9.605/1998, a responsabilidade penal da pessoa jurídica:",["não exclui a das pessoas físicas autoras, coautoras ou partícipes do mesmo fato","exclui a responsabilidade dos sócios e administradores","só existe se o dano for irreversível","depende da condenação prévia de um dirigente"],"As responsabilidades são independentes. O STF afastou a exigência de dupla imputação (RE 548.181).","Art. 3º, parágrafo único, da Lei 9.605/1998",["As pessoas físicas também podem responder.","A lei não exige dano irreversível.","Não é preciso condenar antes um dirigente."]],
["Crimes ambientais","Segundo a Lei 9.605/1998, são penas restritivas de direitos aplicáveis às pessoas físicas:",["prestação de serviços à comunidade, interdição temporária de direitos, suspensão de atividades, prestação pecuniária e recolhimento domiciliar","apenas a multa e a advertência, já que as penas restritivas de direitos da Lei 9.605/1998 só se aplicam às pessoas jurídicas, por meio de suspensão de atividades","reclusão e detenção","apenas a advertência"],"A lei ambiental tem rol próprio de penas restritivas, que inclui o recolhimento domiciliar.","Art. 8º da Lei 9.605/1998",["A lei prevê um rol próprio de penas restritivas para as pessoas físicas, incluindo o recolhimento domiciliar.","Reclusão e detenção são privativas de liberdade.","A lei não prevê advertência como pena."]],
["Crimes ambientais","No crime de guarda de espécime da fauna silvestre, segundo a Lei 9.605/1998, se for caso de guarda doméstica de espécie não ameaçada de extinção:",["o juiz pode, considerando as circunstâncias, deixar de aplicar a pena","a pena é sempre aumentada","o fato é atípico em qualquer caso","a pena é convertida em multa obrigatória"],"É hipótese de perdão judicial prevista na própria lei.","Art. 29, §2º, da Lei 9.605/1998",["A lei não prevê aumento nesse caso.","O fato continua típico; o juiz pode deixar de aplicar a pena.","A lei não impõe conversão em multa."]],
["Reserva legal","Segundo o Código Florestal, o registro da Reserva Legal no Cadastro Ambiental Rural (CAR):",["desobriga a averbação no Cartório de Registro de Imóveis","não produz efeitos sem a averbação em cartório","só vale para imóveis na Amazônia Legal","substitui a obrigação de manter a vegetação"],"O CAR é registro eletrônico nacional, e a inscrição da Reserva Legal nele dispensa a averbação em cartório.","Art. 18, §4º, da Lei 12.651/2012",["A lei dispensa a averbação.","A regra vale em todo o País.","A vegetação deve ser mantida."]],
["LC 140/2011","Segundo a LC 140/2011, inexistindo órgão ambiental capacitado ou conselho de meio ambiente no Estado:",["a União deve desempenhar as ações administrativas estaduais até a sua criação","o licenciamento fica suspenso até a criação do órgão","os Municípios assumem todo o licenciamento estadual","o empreendimento fica dispensado de licença"],"É a atuação supletiva: um ente assume a atribuição de outro enquanto este não tiver órgão capacitado ou conselho de meio ambiente.","Art. 15, I, da LC 140/2011"],
["Unidades de conservação","Segundo a Lei do SNUC, devem possuir zona de amortecimento todas as unidades de conservação, EXCETO:",["a Área de Proteção Ambiental e a Reserva Particular do Patrimônio Natural","os Parques Nacionais e as Estações Ecológicas, por serem de proteção integral","as Estações Ecológicas","as Reservas Biológicas"],"Zona de amortecimento é o entorno da unidade, sujeito a regras para reduzir impactos.","Art. 25 da Lei 9.985/2000",["Parques e Estações Ecológicas devem ter zona de amortecimento.","Estações Ecológicas devem ter.","Reservas Biológicas devem ter."]],
["Unidades de conservação","Segundo a Lei do SNUC, o Parque Nacional:",["é de posse e domínio públicos, e as áreas particulares incluídas em seus limites devem ser desapropriadas","pode ter terras particulares, sem desapropriação","é unidade de uso sustentável, que admite terras particulares sem desapropriação e a exploração de madeira","admite a exploração de madeira por particulares"],"O Parque Nacional é unidade de proteção integral, que admite visitação e pesquisa.","Art. 11, §1º, da Lei 9.985/2000",["As áreas particulares devem ser desapropriadas.","O Parque Nacional é de proteção integral, de posse e domínio públicos.","Não admite exploração madeireira."]],
["Unidades de conservação","A Área de Proteção Ambiental (APA) pertence ao grupo das unidades de:",["uso sustentável","proteção integral","conservação estrita","domínio exclusivamente público"],"As unidades de proteção integral admitem apenas uso indireto dos recursos.","Arts. 7º e 14 da Lei 9.985/2000"],
["Recursos hídricos","Segundo a Política Nacional de Recursos Hídricos, a água é:",["bem de domínio público e recurso natural limitado, dotado de valor econômico","bem privado do dono do terreno onde está a nascente","recurso ilimitado e gratuito","bem exclusivo da União"],"Por ter valor econômico, o uso da água pode ser cobrado, mediante outorga.","Art. 1º, I e II, da Lei 9.433/1997",["A água é bem público.","A lei a define como recurso limitado e com valor econômico.","Há águas da União e dos Estados (arts. 20 e 26 da Constituição)."]],
["Resíduos sólidos","Segundo a Política Nacional de Resíduos Sólidos, é proibida a seguinte forma de destinação final de resíduos ou rejeitos:",["lançamento in natura a céu aberto, salvo resíduos de mineração","disposição em aterro sanitário licenciado","reciclagem","compostagem"],"Também são proibidos o lançamento em corpos hídricos e a queima a céu aberto.","Art. 47, II, da Lei 12.305/2010",["O aterro licenciado é forma adequada de disposição.","A reciclagem é estimulada.","A compostagem é estimulada."]],
["Competência","Proteger o meio ambiente e combater a poluição em qualquer de suas formas é competência:",["comum da União, dos Estados, do DF e dos Municípios","privativa da União, cabendo aos demais entes apenas fiscalizar","exclusiva dos Municípios","residual dos Estados"],"A competência legislativa sobre florestas e proteção ambiental é concorrente (art. 24, VI).","Art. 23, VI, da Constituição"],
["Crimes ambientais","Na Lei de Crimes Ambientais, as penas restritivas de direitos são autônomas e substituem as privativas de liberdade quando:",["se tratar de crime culposo ou for aplicada pena privativa de liberdade inferior a 4 anos","a pena for inferior a 2 anos e o réu for primário","houver reparação integral do dano","o crime for praticado por pessoa jurídica"],"Também se exige que as circunstâncias indiquem a suficiência da substituição.","Art. 7º da Lei 9.605/1998"]
]);
addQ("eca","eca","xc",1,[
["Família","Segundo o ECA, a falta ou a carência de recursos materiais:",["não constitui motivo suficiente para a perda ou a suspensão do poder familiar","autoriza a perda ou a suspensão do poder familiar, desde que comprovada por estudo social","autoriza a adoção imediata da criança","obriga o acolhimento institucional"],"Nesses casos, a família deve ser incluída em programas de proteção e apoio.","Art. 23 do ECA (Lei 8.069/1990)",["A pobreza não basta para a perda ou suspensão do poder familiar.","A pobreza não autoriza a adoção.","O acolhimento é medida excepcional."]],
["Conselho Tutelar","Segundo o ECA, os dirigentes de estabelecimentos de ensino fundamental devem comunicar ao Conselho Tutelar os casos de:",["maus-tratos, reiteração de faltas injustificadas e evasão escolar, e elevados níveis de repetência","notas baixas em uma disciplina, mudança de endereço da família e matrícula do aluno em escola particular","mudança de endereço da família","matrícula em escola particular"],"A escola é parte da rede de proteção.","Art. 56 do ECA (Lei 8.069/1990)",["A escola comunica maus-tratos, faltas reiteradas, evasão e elevada repetência.","Mudança de endereço não está na lista.","A matrícula em escola particular não está na lista."]],
["Direitos fundamentais","Segundo o ECA, as medidas de proteção à criança e ao adolescente são aplicáveis sempre que seus direitos forem ameaçados ou violados:",["por ação ou omissão da sociedade ou do Estado, por falta, omissão ou abuso dos pais, ou em razão de sua própria conduta","somente quando praticarem ato infracional","somente por decisão do Ministério Público","somente quando os pais pedirem ou quando a criança praticar ato infracional, por decisão exclusiva do Ministério Público"],"As medidas de proteção não são punição. São aplicadas pelo Conselho Tutelar ou pelo juiz.","Art. 98 do ECA (Lei 8.069/1990)",["As medidas não dependem de ato infracional.","O Conselho Tutelar e o juiz também aplicam.","As medidas de proteção cabem sempre que os direitos forem ameaçados ou violados por sociedade, Estado, pais ou pela própria conduta."]],
["Acolhimento","Segundo o ECA, o acolhimento institucional e o acolhimento familiar são medidas:",["provisórias e excepcionais, de transição para a reintegração familiar ou, não sendo possível, para família substituta, sem privação de liberdade","definitivas, que substituem a família de origem","punitivas, aplicadas ao adolescente infrator","que dependem de pedido da criança ou do adolescente e são definitivas, substituindo a família de origem, com caráter punitivo para o adolescente infrator"],"O acolhimento é uma ponte, e não um fim.","Art. 101, §1º, do ECA (Lei 8.069/1990)",["As medidas são provisórias.","Não são medidas socioeducativas.","O acolhimento é provisório e excepcional, de transição, e não implica privação de liberdade."]],
["Acolhimento","Segundo o ECA, entre o acolhimento familiar e o institucional:",["o acolhimento familiar tem preferência","o institucional tem preferência, por ser mais seguro","não há preferência legal","o institucional é obrigatório para menores de 6 anos"],"A convivência em família acolhedora é considerada melhor para o desenvolvimento da criança.","Art. 34, §1º, do ECA (Lei 8.069/1990)",["A lei prefere o acolhimento familiar.","A lei estabelece preferência.","A lei não traz essa regra."]],
["Maioridade","A superveniência da maioridade penal:",["não interfere na apuração de ato infracional nem na aplicação de medida socioeducativa, inclusive internação, enquanto não atingidos 21 anos","extingue automaticamente o procedimento","converte a medida socioeducativa em pena, que passa a ser cumprida em presídio comum até o fim do prazo fixado, ou extingue automaticamente o procedimento","impede a aplicação da internação"],"O que importa é a idade na data do fato.","Súmula 605 do STJ; art. 104, parágrafo único, do ECA"],
["Medidas socioeducativas","Segundo o ECA, em se tratando de ato infracional com reflexos patrimoniais, a autoridade poderá determinar que o adolescente:",["restitua a coisa, promova o ressarcimento do dano ou, por outra forma, compense o prejuízo da vítima","pague multa ao Estado ou cumpra pena de prisão simples, conforme o valor do prejuízo causado à vítima","cumpra pena de prisão simples","perca o direito de estudar"],"É a medida de obrigação de reparar o dano.","Art. 116 do ECA (Lei 8.069/1990)",["O ECA prevê a obrigação de reparar o dano, restituindo, ressarcindo ou compensando a vítima.","Adolescente não cumpre pena.","Educação é direito que não pode ser retirado."]],
["Adoção","Segundo o ECA, para a adoção conjunta, é indispensável que os adotantes:",["sejam casados civilmente ou mantenham união estável, comprovada a estabilidade da família","sejam casados há pelo menos cinco anos","tenham a mesma idade e sejam casados há pelo menos cinco anos, com comprovação de renda mínima","sejam parentes do adotando"],"A adoção conjunta exige casamento ou união estável e estabilidade familiar. Divorciados e ex-companheiros podem adotar em conjunto em situações específicas do §4º do art. 42.","Art. 42, §2º, do ECA (Lei 8.069/1990)"],
["Internação","Segundo o ECA, entre os direitos do adolescente privado de liberdade está o de:",["receber visitas, ao menos, semanalmente","sair da unidade nos fins de semana, em qualquer caso","escolher a unidade de internação","ser liberado após trinta dias"],"Também tem direito de entrevistar-se pessoalmente com o promotor e de peticionar a qualquer autoridade.","Art. 124, VII, do ECA (Lei 8.069/1990)",["Atividades externas dependem de decisão.","Não há escolha da unidade.","A internação dura até três anos, com reavaliação semestral."]],
["Remissão","Segundo o ECA, a remissão pode incluir a aplicação de medidas previstas em lei, EXCETO:",["a semiliberdade e a internação","a advertência","a prestação de serviços à comunidade","a liberdade assistida"],"A remissão não pode vir acompanhada de medidas privativas de liberdade.","Art. 127 do ECA (Lei 8.069/1990)",["A advertência pode ser incluída.","A prestação de serviços pode ser incluída.","A liberdade assistida pode ser incluída."]],
["Adoção","Segundo o ECA, a adoção atribui ao adotado a condição de filho:",["com os mesmos direitos e deveres, desligando-o de qualquer vínculo com pais e parentes, salvo os impedimentos matrimoniais","com direitos menores que os dos filhos biológicos","mantendo os vínculos com a família biológica para todos os efeitos","apenas para fins de herança, mantendo os vínculos com a família biológica para todos os demais efeitos, inclusive o poder familiar"],"Na adoção unilateral, mantêm-se os vínculos com o cônjuge do adotante e seus parentes.","Art. 41 do ECA (Lei 8.069/1990)",["A Constituição proíbe distinção entre filhos.","Os vínculos com a família biológica são desfeitos.","A adoção desliga o adotado da família biológica, salvo impedimentos matrimoniais."]],
["Conselho Tutelar","Segundo o ECA, as decisões do Conselho Tutelar:",["somente poderão ser revistas pela autoridade judiciária, a pedido de quem tenha legítimo interesse","podem ser revistas pelo Prefeito ou pela Câmara Municipal, por meio de recurso administrativo próprio","são irrecorríveis e não podem ser revistas","dependem de homologação do Ministério Público"],"O Conselho Tutelar é autônomo. Só o juiz pode rever suas decisões, a pedido de quem tenha legítimo interesse.","Art. 137 do ECA (Lei 8.069/1990)"],
["Adoção","O prazo máximo para conclusão da ação de adoção é de:",["120 dias, prorrogável uma única vez por igual período","60 dias, improrrogável","1 ano, prorrogável por mais 1 ano mediante decisão fundamentada","2 anos"],"A Lei 13.509/2017 buscou acelerar os processos de adoção.","Art. 47, §10, do ECA"],
["Adoção","Segundo o ECA, a morte dos adotantes:",["não restabelece o poder familiar dos pais naturais","restabelece automaticamente o poder familiar dos pais biológicos","anula a adoção","transfere a guarda ao Conselho Tutelar"],"A adoção é irrevogável. Com a morte dos adotantes, a criança pode ser posta em tutela ou em nova adoção.","Art. 49 do ECA (Lei 8.069/1990)",["O poder familiar dos pais biológicos não volta.","A adoção não é anulada.","O Conselho Tutelar não recebe a guarda."]],
["Proteção integral","A doutrina adotada pelo ECA é a da:",["proteção integral, que reconhece crianças e adolescentes como sujeitos de direitos, com prioridade absoluta","situação irregular, voltada apenas ao menor abandonado ou infrator","tutela penal do menor","capacidade progressiva sem prioridade"],"O Código de Menores de 1979 adotava a doutrina da situação irregular.","Art. 227 da Constituição; arts. 1º e 4º do ECA"]
]);
addQ("cdc","cdc","xk",1,[
["Conceitos","Segundo o CDC, a Política Nacional das Relações de Consumo atende, entre outros, ao princípio do:",["reconhecimento da vulnerabilidade do consumidor no mercado de consumo","reconhecimento da superioridade do fornecedor","livre arbítrio do fornecedor na fixação de cláusulas","igualdade absoluta entre consumidor e fornecedor"],"A vulnerabilidade é presumida para todo consumidor e justifica a proteção do CDC.","Art. 4º, I, do CDC (Lei 8.078/1990)",["O CDC não reconhece superioridade do fornecedor.","O CDC limita as cláusulas.","O CDC parte da desigualdade entre as partes."]],
["Fato do produto","Segundo o CDC, o fornecedor não poderá colocar no mercado produto ou serviço que:",["sabe ou deveria saber apresentar alto grau de nocividade ou periculosidade à saúde ou segurança","seja importado sem manual em língua estrangeira ou tenha preço acima da média praticada no mercado regional","tenha preço acima da média do mercado","não tenha manual em inglês"],"Se descobrir a periculosidade depois, deve comunicar as autoridades e os consumidores (recall).","Art. 10 do CDC (Lei 8.078/1990)",["O CDC proíbe colocar no mercado produto que o fornecedor sabe ou deveria saber ser altamente nocivo ou perigoso.","O preço não é o critério.","O CDC exige informações em português."]],
["Vício do produto","Segundo o CDC, são impróprios ao uso e consumo, entre outros, os produtos:",["cujos prazos de validade estejam vencidos","vendidos em promoção","fabricados no exterior","comprados pela internet"],"Também são impróprios os deteriorados, adulterados, falsificados ou nocivos.","Art. 18, §6º, I, do CDC (Lei 8.078/1990)",["A promoção não torna o produto impróprio.","A origem não torna o produto impróprio.","O canal de venda não torna o produto impróprio."]],
["Oferta","Segundo o CDC, os fabricantes e importadores devem assegurar a oferta de componentes e peças de reposição:",["enquanto não cessar a fabricação ou importação e, depois disso, por período razoável de tempo, na forma da lei","apenas durante o prazo da garantia contratual","apenas durante noventa dias após a venda ou durante o prazo da garantia contratual, o que for maior, cessando depois a obrigação","somente se o consumidor pagar taxa de manutenção"],"A obrigação continua mesmo depois que o produto deixa de ser fabricado, por um período razoável.","Art. 32 do CDC (Lei 8.078/1990)"],
["Vício do produto","Segundo o CDC, a ignorância do fornecedor sobre os vícios de qualidade por inadequação dos produtos e serviços:",["não o exime de responsabilidade","o exime de responsabilidade, se provar boa-fé","reduz a indenização pela metade","transfere a responsabilidade ao fabricante"],"A responsabilidade por vício é objetiva.","Art. 23 do CDC (Lei 8.078/1990)",["A boa-fé não exime o fornecedor.","Não há redução.","Os fornecedores respondem solidariamente pelo vício."]],
["Cláusulas abusivas","Segundo o CDC, nos contratos de consumo, é vedada a cláusula que:",["impossibilite, exonere ou atenue a obrigação de indenizar","preveja multa moratória de 2%","estabeleça foro no domicílio do consumidor","conceda desconto para pagamento antecipado"],"A obrigação de indenizar prevista no CDC não pode ser afastada nem reduzida por contrato.","Art. 25 do CDC (Lei 8.078/1990)",["A multa de 2% é o limite permitido.","O foro no domicílio do consumidor é favorável a ele.","O desconto é favorável ao consumidor."]],
["Oferta","Segundo o CDC, a oferta suficientemente precisa, veiculada por qualquer meio:",["obriga o fornecedor que a fizer veicular e integra o contrato que vier a ser celebrado","não obriga o fornecedor, sendo mero convite","só obriga o fornecedor se publicada em jornal de grande circulação e assinada pelo seu representante legal","só obriga se assinada pelo fornecedor"],"É o princípio da vinculação da oferta.","Art. 30 do CDC (Lei 8.078/1990)",["No CDC, a oferta vincula.","No CDC, a oferta precisa obriga, por qualquer meio de comunicação.","Não é preciso assinatura."]],
["Publicidade","Segundo o CDC, a publicidade é enganosa por omissão quando:",["deixar de informar sobre dado essencial do produto ou serviço","comparar o produto com o de concorrentes","usar linguagem informal","não informar o endereço da sede do fornecedor"],"Omitir dado essencial pode levar o consumidor a erro tanto quanto uma afirmação falsa.","Art. 37, §§1º e 3º, do CDC (Lei 8.078/1990)"],
["Publicidade","Segundo o CDC, é proibida a publicidade de bens e serviços por telefone:",["quando a chamada for onerosa ao consumidor que a origina","em qualquer horário","quando feita por empresa estrangeira","quando o consumidor já for cliente"],"A regra foi incluída pela Lei 11.800/2008.","Art. 33, parágrafo único, do CDC (Lei 8.078/1990)",["A proibição não é por horário.","A origem da empresa não importa.","A regra não trata de clientes."]],
["Contrato de adesão","Segundo o CDC, as cláusulas contratuais nos contratos de consumo:",["serão interpretadas de maneira mais favorável ao consumidor","serão interpretadas de maneira mais favorável a quem as redigiu","devem ser interpretadas sempre de forma literal","só podem ser interpretadas pelo Procon"],"A regra decorre da vulnerabilidade do consumidor.","Art. 47 do CDC (Lei 8.078/1990)",["É o contrário: a interpretação favorece o consumidor.","O CDC não impõe interpretação literal.","O juiz interpreta o contrato."]],
["Cobrança","Segundo o CDC, em todos os documentos de cobrança de débitos apresentados ao consumidor, deverão constar:",["o nome, o endereço e o número do CPF ou do CNPJ do fornecedor","apenas o valor da dívida","apenas o valor da dívida, a data de vencimento e a foto do devedor para identificação","o nome dos fiadores"],"A regra dá transparência e permite ao consumidor identificar quem cobra.","Art. 42-A do CDC (Lei 8.078/1990)",["O valor sozinho não basta.","O documento de cobrança deve trazer nome, endereço e CPF ou CNPJ do fornecedor.","Os fiadores não precisam constar."]],
["Instituições financeiras","O Código de Defesa do Consumidor:",["é aplicável às instituições financeiras","não se aplica às instituições financeiras","só se aplica aos bancos públicos","só se aplica aos contratos de cartão de crédito"],"O STF também confirmou a aplicação na ADI 2.591.","Súmula 297 do STJ"],
["Banco de dados","Segundo o CDC, consumada a prescrição relativa à cobrança de débitos do consumidor:",["os sistemas de proteção ao crédito não podem fornecer informações que impeçam ou dificultem novo acesso ao crédito","a dívida deve permanecer no cadastro por mais dez anos","o consumidor deve pagar a dívida para sair do cadastro","o fornecedor pode protestar o título e manter o nome do consumidor no cadastro de inadimplentes até que a dívida seja paga"],"Além disso, informações negativas não podem ficar por mais de cinco anos (§1º).","Art. 43, §5º, do CDC (Lei 8.078/1990)",["O CDC proíbe a manutenção.","A prescrição impede a restrição.","Consumada a prescrição, os cadastros não podem fornecer informações que dificultem novo crédito."]],
["Contrato de adesão","Segundo o CDC, os contratos que regulam as relações de consumo não obrigam os consumidores se:",["não lhes for dada oportunidade de conhecer previamente seu conteúdo, ou se forem redigidos de modo a dificultar a compreensão","não forem registrados em cartório","forem assinados digitalmente, sem a presença física do vendedor, ou não forem registrados em cartório de títulos e documentos","não forem lidos em voz alta pelo vendedor"],"É o dever de transparência e de informação na formação do contrato.","Art. 46 do CDC (Lei 8.078/1990)",["O CDC não exige registro.","A assinatura digital é válida e o CDC não exige registro; o problema é a falta de conhecimento prévio do conteúdo.","O CDC não exige leitura em voz alta."]],
["Cláusulas abusivas","Segundo o CDC, a nulidade de uma cláusula abusiva:",["não invalida o contrato, exceto quando sua ausência, apesar dos esforços de integração, gerar ônus excessivo a qualquer das partes","invalida sempre todo o contrato, que deve ser refeito pelas partes, e só pode ser declarada em ação proposta pelo Ministério Público","depende de ação do Ministério Público","só pode ser declarada se o consumidor provar dolo"],"É o princípio da conservação do contrato.","Art. 51, §2º, do CDC (Lei 8.078/1990)",["A nulidade da cláusula não invalida o contrato, salvo ônus excessivo, e pode ser alegada pelo próprio consumidor.","O próprio consumidor pode pedir a nulidade.","A nulidade não depende de dolo."]]
]);
addQ("prev","prev","xv",1,[
["Custeio","Segundo a Constituição, os ganhos habituais do empregado, a qualquer título:",["serão incorporados ao salário para efeito de contribuição previdenciária e consequente repercussão em benefícios, nos casos e na forma da lei","nunca integram a base de contribuição previdenciária, por não terem natureza salarial nem repercussão nos benefícios futuros do empregado, mesmo se pagos todo mês","integram a base de contribuição, mas não repercutem nos benefícios","só integram o salário se pagos em dinheiro e mensalmente"],"Parcelas habituais entram na base de contribuição e, por isso, também aumentam o valor dos benefícios.","Art. 201, §11, da Constituição"],
["Benefícios","Segundo a Constituição, os benefícios previdenciários devem ser reajustados para:",["preservar-lhes, em caráter permanente, o valor real, conforme critérios da lei","acompanhar sempre o aumento do salário mínimo","acompanhar a inflação apenas a cada cinco anos","garantir aumento real acima da inflação"],"Benefícios acima do mínimo seguem o índice da lei; os de valor mínimo acompanham o salário mínimo.","Art. 201, §4º, da Constituição",["Só os benefícios de valor mínimo acompanham o salário mínimo.","O reajuste é periódico, não a cada cinco anos.","A Constituição garante o valor real, e não aumento real."]],
["Aposentadoria por incapacidade","Segundo a Lei 8.213/1991, a doença ou lesão de que o segurado já era portador ao filiar-se ao RGPS:",["não dá direito à aposentadoria por incapacidade, salvo quando a incapacidade sobrevier por progressão ou agravamento","sempre dá direito à aposentadoria, sem carência","dá direito apenas ao BPC, nunca a benefício previdenciário, mesmo que a incapacidade surja depois por progressão ou agravamento","exclui a filiação ao RGPS"],"A regra impede a filiação oportunista, mas protege quem se agravou depois.","Art. 42, §2º, da Lei 8.213/1991",["A lei restringe esse direito.","Não há direito à aposentadoria por incapacidade preexistente, salvo se a incapacidade vier por progressão ou agravamento.","A doença não impede a filiação."]],
["Auxílio por incapacidade","Segundo a Lei 8.213/1991, não fixado o prazo estimado de duração do auxílio por incapacidade temporária, o benefício:",["cessa após 120 dias da concessão ou reativação, salvo pedido de prorrogação","dura até a aposentadoria","dura um ano, sem possibilidade de prorrogação","só cessa por decisão judicial"],"É a chamada alta programada, introduzida pela Lei 13.457/2017.","Art. 60, §§8º e 9º, da Lei 8.213/1991",["O benefício é temporário.","Cabe pedido de prorrogação.","A cessação é administrativa."]],
["Salário-família","Segundo a Lei 8.213/1991, o salário-família é pago por filho ou equiparado de qualquer condição:",["até 14 anos de idade ou inválido de qualquer idade","até 21 anos de idade","até 18 anos, se estudante","até 24 anos, se universitário"],"É devido ao segurado de baixa renda empregado, doméstico ou avulso.","Arts. 65 e 66 da Lei 8.213/1991",["Vinte e um anos é o limite da pensão por morte do filho.","Dezoito anos não é o limite.","A lei previdenciária não estende por estudo universitário."]],
["Salário-maternidade","Segundo a Lei 8.213/1991, o salário-maternidade da segurada empregada:",["consiste em renda mensal igual à sua remuneração integral, paga pela empresa, que compensa o valor","é sempre de um salário mínimo, pago diretamente pelo INSS, qualquer que seja a remuneração da segurada empregada","é limitado a metade da remuneração","é pago só depois do parto, em parcela única"],"A empresa paga e depois compensa nas contribuições. Para a doméstica e a avulsa, entre outras, o INSS paga diretamente.","Art. 72 da Lei 8.213/1991",["A empregada recebe renda igual à remuneração integral, paga pela empresa, que compensa o valor.","Não há limite de metade.","O pagamento é mensal."]],
["Pensão por morte","Segundo a Lei 8.213/1991, a pensão por morte é devida desde o óbito quando requerida em até:",["180 dias, para filhos menores de 16 anos, ou 90 dias, para os demais dependentes","30 dias para todos os dependentes","um ano para todos os dependentes, contado da data do óbito, sem distinção de idade entre eles","cinco anos para todos os dependentes"],"Requerida depois desses prazos, a pensão é devida a partir do requerimento.","Art. 74, I e II, da Lei 8.213/1991",["Trinta dias não é o prazo.","A pensão é devida desde o óbito se requerida em 180 dias (filhos menores de 16) ou 90 dias (demais).","Cinco anos é a prescrição das parcelas."]],
["Carência","Segundo a Lei 8.213/1991, a carência exigida para o auxílio-reclusão é de:",["24 contribuições mensais","12 contribuições mensais","180 contribuições mensais","nenhuma contribuição"],"A carência foi criada pela Lei 13.846/2019. O benefício é devido aos dependentes do segurado de baixa renda em regime fechado.","Art. 25, IV, da Lei 8.213/1991",["Doze contribuições é a regra do auxílio por incapacidade.","Cento e oitenta é a carência da aposentadoria programada.","Desde 2019 há carência."]],
["Auxílio-acidente","Segundo a Lei 8.213/1991, o recebimento de salário ou a concessão de outro benefício pelo segurado:",["não prejudica a continuidade do auxílio-acidente, exceto no caso de aposentadoria","sempre suspende o auxílio-acidente enquanto durar o vínculo de emprego ou o outro benefício concedido","extingue o auxílio-acidente em qualquer caso","reduz o auxílio-acidente pela metade"],"O auxílio-acidente é indenizatório, e o segurado pode continuar trabalhando.","Art. 86, §§2º e 3º, da Lei 8.213/1991",["O salário ou outro benefício não prejudica o auxílio-acidente, salvo a aposentadoria.","Só a aposentadoria impede a acumulação.","Não há redução."]],
["Segurados","Segundo a Constituição, a lei instituirá sistema especial de inclusão previdenciária, com alíquotas diferenciadas, para atender:",["aos trabalhadores de baixa renda, inclusive informais, e a quem, sem renda própria, se dedique exclusivamente ao trabalho doméstico em sua residência, sendo de família de baixa renda","apenas aos servidores públicos titulares de cargo efetivo de baixa renda, vinculados a regimes próprios, excluídos os trabalhadores informais e as pessoas dedicadas ao trabalho doméstico na própria residência","apenas aos trabalhadores rurais com carteira assinada","aos empresários de grande porte"],"O sistema especial busca incluir na Previdência quem tem pouca ou nenhuma renda, como a dona de casa de família de baixa renda.","Art. 201, §12, da Constituição"],
["Custeio","Segundo a Lei 8.212/1991, a empresa é obrigada a:",["arrecadar as contribuições dos segurados empregados e avulsos a seu serviço, descontando-as da remuneração","recolher a contribuição dos empregados apenas se eles autorizarem","pagar a contribuição do empregado sem desconto","deixar a cargo de cada empregado o recolhimento"],"A empresa desconta e repassa a contribuição do empregado.","Art. 30, I, a, da Lei 8.212/1991",["O desconto é obrigatório.","A contribuição é do empregado, descontada.","O recolhimento é responsabilidade da empresa."]],
["Segurados","Segundo a Constituição, o segurado especial (produtor rural, pescador artesanal e familiares em regime de economia familiar, sem empregados permanentes) contribui:",["mediante alíquota sobre o resultado da comercialização da produção","com alíquota fixa de 20% sobre o salário mínimo","apenas se quiser, como facultativo","sobre o valor da terra"],"Mesmo sem vender, o segurado especial tem direito a benefícios no valor mínimo, comprovando a atividade.","Art. 195, §8º, da Constituição",["Vinte por cento é a alíquota do contribuinte individual comum.","Ele é segurado obrigatório.","O valor da terra não é a base."]],
["Custeio","Segundo a Constituição e o STF (Tema 32), as entidades beneficentes de assistência social:",["são imunes às contribuições para a seguridade social, atendidos os requisitos de lei complementar","pagam contribuições normalmente, pois a imunidade constitucional alcança apenas os impostos, não as contribuições sociais","são isentas por decreto do Ministério da Previdência","só têm o benefício se forem públicas"],"Embora o texto diga isentas, o STF entende que se trata de imunidade, e que os requisitos devem estar em lei complementar (hoje a LC 187/2021).","Art. 195, §7º, da Constituição; STF, RE 566.622 (Tema 32); LC 187/2021",["A CF (art. 195, §7º) dá imunidade às contribuições, observados os requisitos de lei complementar.","O benefício decorre da Constituição, com requisitos em lei complementar.","As entidades são privadas sem fins lucrativos."]],
["BPC","Segundo a Lei 8.742/1993, o benefício de prestação continuada (BPC):",["não pode ser acumulado com outro benefício da seguridade, salvo exceções legais como a assistência médica e a pensão especial de natureza indenizatória","pode ser acumulado com aposentadoria","pode ser acumulado com qualquer pensão por morte","gera direito a 13º salário e pode ser acumulado com aposentadoria e pensão por morte, por ter natureza previdenciária e ser pago a quem contribuiu ao RGPS por quinze anos"],"O BPC é assistencial e personalíssimo. A lei também admite acumular com transferências de renda como o Bolsa Família.","Art. 20, §4º, da Lei 8.742/1993",["Não pode ser acumulado com aposentadoria.","A pensão por morte previdenciária não pode ser acumulada.","O BPC é assistencial, sem 13º, e não se acumula com outro benefício da seguridade, salvo exceções."]],
["Previdência complementar","Segundo a Constituição, as contribuições do empregador e os benefícios dos planos de previdência privada complementar:",["não integram o contrato de trabalho dos participantes, nem a remuneração, salvo os benefícios concedidos","integram o salário para todos os efeitos","são pagos pelo INSS e integram a remuneração do empregado para todos os efeitos do contrato de trabalho e da rescisão","são obrigatórios para todos os empregados"],"A previdência complementar é autônoma em relação ao RGPS e facultativa.","Art. 202, §2º, da Constituição",["A Constituição afasta a integração ao salário.","Essas contribuições e benefícios não integram o contrato de trabalho nem a remuneração, salvo os concedidos.","A previdência complementar é facultativa."]]
]);
